export const eco5Tasks={"conservation": [{"id": "compare", "title": "Predict and explain the evidence", "kind": "conservation", "type": "compare", "cases": [["0", "Which action directly supports endangered-species numbers?", ["A suitable breeding programme", "Removing all remaining habitat", "Increasing unmanaged pollution"], 0, "Breeding can help, while habitat and genetic/management needs still matter."], ["1", "Why restore field margins and hedgerows?", ["To make habitat unnecessary", "To provide habitat within farmed landscapes", "To guarantee every pest disappears"], 1, "Consider dependencies and land-use trade-offs."], ["2", "Which action addresses landfill pressure?", ["Dumping the same resources elsewhere unchecked", "Calling every waste harmless", "Recycling suitable resources"], 2, "Recycling can reduce disposal demand."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "conservation-data", "type": "numeric", "prompt": "Fresh programme:12 credits available,7 spent on habitat and4 on recycling. Credits left?", "answer": 1, "unit": "credits", "reasonChoices": ["12−7−4", "Reverse the required comparison", "Use one universal answer for every scenario"], "reason": 0, "why": "Use the supplied quantities, boundary and units."}, {"id": "model", "title": "Meet two goals within a budget", "kind": "conservation-model", "type": "plan", "why": "Complete every stated requirement and keep the conclusion within the model limits."}], "trophic": [{"id": "compare", "title": "Predict and explain the evidence", "kind": "trophic", "type": "compare", "cases": [["0", "Plants and algae that make organic food occupy…", ["Trophic level1", "Trophic level4 by definition", "Every consumer level only"], 0, "Number the producer as the first feeding level."], ["1", "A herbivore eating a producer is a…", ["Tertiary consumer at level4", "Primary consumer at level2", "Producer at level1"], 1, "Follow the supplied feeding relationship."], ["2", "Small soluble products enter decomposers after…", ["An intact leaf diffuses through the cell surface", "Enzymes create food atoms from nothing", "External enzyme digestion followed by diffusion"], 2, "Extracellular digestion precedes uptake."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "trophic-data", "type": "numeric", "prompt": "Fresh chain algae→snail→fish→heron. Trophic level of heron?", "answer": 4, "unit": "level", "reasonChoices": ["Number producers1 then follow each feeding arrow", "Reverse the required comparison", "Use one universal answer for every scenario"], "reason": 0, "why": "Use the supplied quantities, boundary and units."}, {"id": "model", "title": "Build extracellular digestion", "kind": "trophic-model", "type": "sequence", "why": "Complete every stated requirement and keep the conclusion within the model limits.", "route": ["secrete", "digest", "diffuse"], "labels": ["Secrete enzymes outside the microorganism", "Digest large molecules into small soluble products", "Products diffuse into the microorganism"]}], "pyramids": [{"id": "compare", "title": "Predict and explain the evidence", "kind": "pyramids", "type": "compare", "cases": [["0", "What determines a biomass bar width here?", ["Biomass at that trophic level using one scale", "Only the number of species names", "An arbitrary decorative width"], 0, "A common scale makes widths quantitatively comparable."], ["1", "Which level belongs at the base?", ["The smallest bar regardless of its label", "Producers", "Tertiary consumers by definition"], 1, "Label the feeding level, not just the shape."], ["2", "Our primary160 and producer800 have ratio…", ["5", "640", "0.2"], 2, "Divide primary biomass by producer biomass."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "pyramids-data", "type": "numeric", "prompt": "Producer800, primary160 g/m². Ratio of primary to producer biomass?", "answer": 0.2, "unit": "ratio", "reasonChoices": ["160÷800", "Reverse the required comparison", "Use one universal answer for every scenario"], "reason": 0, "why": "Use the supplied quantities, boundary and units."}, {"id": "model", "title": "Construct the biomass pyramid", "kind": "pyramids-model", "type": "pyramid", "why": "Complete every stated requirement and keep the conclusion within the model limits."}], "biomass": [{"id": "compare", "title": "Predict and explain the evidence", "kind": "biomass", "type": "compare", "cases": [["0", "The approximate1% statement refers to…", ["Incident light energy captured for photosynthesis", "Every organism’s biomass transfer exactly", "The fraction of species alive"], 0, "Energy and biomass are different quantities."], ["1", "Which route removes unabsorbed material?", ["Atoms vanishing", "Egestion as faeces", "Photosynthesis in every animal"], 1, "Do not confuse egestion with absorbed substrate used in respiration."], ["2", "1000→120 g/m² transfer has efficiency…", ["120%", "0.12%", "12%"], 2, "120/1000×100=12."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "biomass-data", "type": "numeric", "prompt": "Fresh transfer:800→96 g/m². Calculate transfer efficiency.", "answer": 12, "unit": "%", "reasonChoices": ["96÷800×100", "Reverse the required comparison", "Use one universal answer for every scenario"], "reason": 0, "why": "Use the supplied quantities, boundary and units."}, {"id": "model", "title": "Account for original organic material", "kind": "biomass-model", "type": "allocation", "why": "Complete every stated requirement and keep the conclusion within the model limits."}], "food-security": [{"id": "compare", "title": "Predict and explain the evidence", "kind": "food-security", "type": "compare", "cases": [["0", "Food security is about…", ["Enough food to feed a population", "Only the number of tractors", "Only maximising one crop without context"], 0, "Quantity, access and needs belong in the evaluation."], ["1", "Which can threaten production?", ["Every increase in crop health", "Pests, pathogens and failed rains", "Only spelling of a crop name"], 1, "Trace the biological or environmental mechanism."], ["2", "100 people need2 units each. Demand is…", ["50 units", "102 units", "200 units"], 2, "Multiply population by the stated per-person requirement."]]}, {"id": "calculate", "title": "Calculate a fresh result", "kind": "food-security-data", "type": "numeric", "prompt": "Fresh scenario:120 people need2 units each,210 available. Calculate shortfall.", "answer": 30, "unit": "food-equivalent units", "reasonChoices": ["120×2−210", "Reverse the required comparison", "Use one universal answer for every scenario"], "reason": 0, "why": "Use the supplied quantities, boundary and units."}, {"id": "model", "title": "Compare six supply-demand scenarios", "kind": "food-security-model", "type": "supply", "why": "Complete every stated requirement and keep the conclusion within the model limits."}]};
export const tasksForEco5=k=>eco5Tasks[k];export const validEco5=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const advanceEco5=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;export const numericEco5=(v,a,t=.001)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<t;
export const policies={margins:{label:'Field margins',cost:6,habitat:4,waste:0},recycling:{label:'Recycling',cost:4,habitat:0,waste:20},breeding:{label:'Breeding programme',cost:5,habitat:0,waste:0}};
export function planTotals(keys=[]){if(!Array.isArray(keys)||new Set(keys).size!==keys.length||keys.some(k=>!policies[k]))throw new RangeError('Choose each named programme once.');return keys.reduce((a,k)=>({cost:a.cost+policies[k].cost,habitat:a.habitat+policies[k].habitat,waste:a.waste+policies[k].waste}),{cost:0,habitat:0,waste:0});}
export function planValid(v){let n=planTotals(v.selected||[]);return n.cost<=10&&n.habitat>=4&&n.waste>=20&&v.reason==='bounded';}
export const pyramidMasses=[800,160,32,6.4];export function pyramidValid(v){return v.base==='producers'&&Number(v.scale)===1000&&pyramidMasses.every((n,i)=>numericEco5(v.masses?.[i],n));}
export function allocationValid(v){return numericEco5(v.faeces,20)&&numericEco5(v.respired,70)&&numericEco5(v.growth,10)&&v.reason==='organic';}
export const supplyCases={baseline:{label:'Baseline',population:100,produced:240,available:240},population:{label:'Larger population',population:140,produced:240,available:240},drought:{label:'Failed rains',population:100,produced:160,available:160},pests:{label:'Crop pests',population:100,produced:180,available:180},cost:{label:'Higher input costs',population:100,produced:190,available:190},conflict:{label:'Conflict/access',population:100,produced:220,available:120}};
export function supplyResult(key){let s=supplyCases[key];if(!s)throw new RangeError('Choose a named scenario.');let demand=s.population*2;return{...s,demand,shortfall:Math.max(0,demand-s.available),surplus:Math.max(0,s.available-demand)};}
export const supplyValid=v=>Object.keys(supplyCases).every(k=>v.observed?.includes(k))&&v.reason==='limited';
